function renderExam(){const root=$('#examPreview');if(!state.exam?.examCodes?.length){root.innerHTML='';return}const mat=sourcePayload().read;root.innerHTML=state.exam.examCodes.map(code=>`<div class="preview-code">${outputHeaderHtml('exam',code.code||'A')}<div class="part-heading">PHẦN I. ĐỌC (${fmt($('#readScore').value)} điểm)</div><p><b>Đọc văn bản và thực hiện yêu cầu bên dưới:</b></p>${materialHtml(mat)}${(code.readQuestions||[]).map(qHtml).join('')}<div class="part-heading">PHẦN II. VIẾT (${fmt($('#writeScore').value)} điểm)</div><div class="preview-q"><b>${esc(code.write?.prompt||'Chưa có yêu cầu Viết.')}</b></div><div style="text-align:center;font-weight:800;margin-top:14px">----- HẾT -----</div></div>`).join('')}
function answerText(q){if(Array.isArray(q.answer))return q.answer.join(', ');if(q.answer&&typeof q.answer==='object')return Object.entries(q.answer).map(([k,v])=>`${k}: ${v===true?'Đ':v===false?'S':v}`).join('; ');return String(q.answer??'')}
function hsktPreviewHtml(){if(!hsktEnabled()||!state.exam?.examCodes?.length)return '';const code=state.exam.examCodes[0],all=(code.readQuestions||[]),use=hsktMode()==='tn10'?all.filter(q=>q.form==='TNKQ'):all;if(!use.length)return `<div class="notice">Phương án HSKT đã chọn không có câu phù hợp. Hãy đổi phương án quy đổi.</div>`;const alloc=quarterAllocation(use,10);return `<h3>HƯỚNG DẪN CHẤM CHO HỌC SINH KHUYẾT TẬT</h3><div class="table-scroll"><table class="review-marking-table"><thead><tr><th>Nội dung thực hiện</th><th>Điểm quy đổi</th></tr></thead><tbody><tr><td><b>PHẦN I. ĐỌC</b><br>${hsktMode()==='tn10'?'Học sinh chỉ thực hiện các câu TNKQ của phần Đọc.':'Học sinh thực hiện phần Đọc.'}</td><td><b>10,0</b></td></tr>${alloc.map(a=>`<tr><td>Câu ${esc(a.question.number)}</td><td>${fmt(a.points)}</td></tr>`).join('')}<tr><td><b>PHẦN II. VIẾT</b><br>Không thực hiện.</td><td>—</td></tr><tr><td colspan="2"><i>Lưu ý: Giáo viên có thể điều chỉnh linh hoạt theo mức độ khuyết tật, kế hoạch giáo dục cá nhân và quy định của đơn vị; tổng điểm quy đổi của phần được thực hiện là 10,0 điểm.</i></td></tr></tbody></table></div>`}
function markingHtml(){
  if(!state.exam?.examCodes?.length)return '<div class="empty-state">Chưa có đề.</div>';
  const codes=state.exam.examCodes;let html=outputHeaderHtml('marking')+`<h3>PHẦN I. ĐỌC (${fmt($('#readScore').value)} điểm)</h3><p class="preview-objective"><i>HS có thể trình bày, diễn đạt theo cách riêng, miễn là hợp lí hoặc tương tự như “Yêu cầu cần đạt”.</i></p>`;
  const tn0=(codes[0].readQuestions||[]).filter(q=>q.form==='TNKQ');
  if(tn0.length){const groups=new Map();tn0.forEach(q=>groups.set(`${q.subtype}|${q.points}`,{subtype:q.subtype,points:q.points}));groups.forEach(g=>{html+=`<div class="marking-rubric">${esc(tnName(g.subtype))}: Mỗi câu đúng được ${fmt(g.points)} điểm.</div>`});html+='<div class="table-scroll"><table class="review-marking-table"><thead><tr><th>Câu</th>'+tn0.map(q=>`<th>${esc(q.number)}</th>`).join('')+'</tr></thead><tbody>';codes.forEach(c=>{const qs=(c.readQuestions||[]).filter(q=>q.form==='TNKQ');html+=`<tr><th>Đề ${esc(c.code)}</th>${qs.map(q=>`<td style="text-align:center">${esc(answerText(q))}</td>`).join('')}</tr>`});html+='</tbody></table></div>'}
  const tlCodes=codes.map(c=>(c.readQuestions||[]).filter(q=>q.form==='TL')),max=Math.max(...tlCodes.map(a=>a.length),0);
  if(max){html+='<h4>II. TỰ LUẬN</h4><div class="table-scroll"><table class="review-marking-table"><thead><tr><th>Câu</th>'+codes.map(c=>`<th>ĐỀ ${esc(c.code)}</th>`).join('')+'<th>Điểm</th></tr></thead><tbody>';for(let i=0;i<max;i++){const qs=tlCodes.map(a=>a[i]);let cells='';qs.forEach(q=>{if(!q){cells+='<td></td>';return}let inside=htmlAnswer(answerText(q));if(q.rubric?.length)inside+='<div class="marking-label">Hướng dẫn chấm:</div>'+htmlRubric(q.rubric);cells+=`<td>${inside}</td>`});html+=`<tr><td style="text-align:center">${esc(qs.find(Boolean)?.number||'')}</td>${cells}<td style="text-align:center">${fmt(qs.find(Boolean)?.points||0)}</td></tr>`}html+='</tbody></table></div>'}
  html+=`<h3>PHẦN II. VIẾT (${fmt($('#writeScore').value)} điểm)</h3><p class="preview-objective"><i>HS có thể trình bày, diễn đạt theo cách riêng, miễn là hợp lí hoặc tương tự như “Yêu cầu cần đạt”.</i></p>`;
  const groupMax=Math.max(...codes.map(c=>(c.write?.rubric||[]).length),0),colspan=codes.length+2;html+='<div class="table-scroll"><table class="review-marking-table write-marking-table"><thead><tr><th>Mục</th>'+codes.map(c=>`<th>ĐỀ ${esc(c.code)}</th>`).join('')+'<th>Điểm</th></tr></thead><tbody>';html+=`<tr><td><b>Yêu cầu</b></td>${codes.map(c=>`<td>${esc(c.write?.prompt||'')}</td>`).join('')}<td></td></tr>`;
  for(let i=0;i<groupMax;i++){const groups=codes.map(c=>(c.write?.rubric||[])[i]),first=groups.find(Boolean),label=first?.group||`Tiêu chí ${i+1}`;const cells=groups.map(g=>{if(!g)return '<td></td>';let inner=g.content?`<div>${esc(g.content)}</div>`:'';(g.details||[]).forEach(d=>{inner+=`<div>– ${esc(d.content||d)}${d.points!=null?` (${fmt(d.points)}đ)`:''}</div>`});return `<td>${inner}</td>`}).join('');html+=`<tr><td><b>${esc(label)}</b></td>${cells}<td style="text-align:center">${first?.points!=null?fmt(first.points):''}</td></tr>`}
  if(codes.some(c=>c.write?.bands?.length))html+=`<tr><td><b>Biểu điểm</b></td>${codes.map(c=>`<td>${(c.write?.bands||[]).map(b=>`<div>– ${esc(b.label)}: ${esc(b.description)}</div>`).join('')}</td>`).join('')}<td></td></tr>`;
  html+=`<tr><td colspan="${colspan-1}"><b>Tổng điểm phần Viết</b></td><td style="text-align:center"><b>${fmt($('#writeScore').value)}</b></td></tr></tbody></table></div>`;html+=hsktPreviewHtml();return html;
}
function matrixHtml(){return objectiveHtml()+`<div class="preview-doc-heading">1. Ma trận</div>`+$('#matrixTable').outerHTML}
function specHtml(){return objectiveHtml()+`<div class="preview-doc-heading">1. Ma trận</div>`+$('#matrixTable').outerHTML+`<div class="preview-doc-heading">2. Bảng đặc tả</div>`+specPreviewTableHtml()+`<div class="preview-doc-heading">IV. ĐỀ KIỂM TRA <i>(trang sau)</i></div>`}
function renderReview(){if(!$('#reviewPreview'))return;$$('.review-tab').forEach(b=>b.classList.toggle('active',b.dataset.reviewTab===state.reviewTab));const titles={matrix:'Ma trận',spec:'Bản đặc tả',exam:'Đề kiểm tra',marking:'Hướng dẫn chấm'};$('#reviewPreviewTitle').textContent=titles[state.reviewTab];if(state.reviewTab==='matrix'){$('#reviewPreview').innerHTML=matrixHtml()}else if(state.reviewTab==='spec'){$('#reviewPreview').innerHTML=specHtml()}else if(state.reviewTab==='exam'){$('#reviewPreview').innerHTML=$('#examPreview').innerHTML||'<div class="empty-state">Chưa tạo đề.</div>'}else $('#reviewPreview').innerHTML=markingHtml();renderAiScopes();renderSafety();updateExportGate();}
function renderAiScopes(){const s=$('#aiScope'),cur=s.value;let h='<option value="">Chọn phạm vi...</option>';for(let ci=0;ci<(state.exam?.examCodes?.length||0);ci++){const c=state.exam.examCodes[ci];h+=`<optgroup label="Đề ${esc(c.code)}">`;for(let qi=0;qi<(c.readQuestions||[]).length;qi++){const q=c.readQuestions[qi];h+=`<option value="read|${ci}|${qi}">Câu ${q.number} – Đọc</option><option value="marking|${ci}|${qi}">HDC câu ${q.number}</option>`}h+=`<option value="write|${ci}|0">Phần Viết</option><option value="writeMarking|${ci}|0">HDC phần Viết</option></optgroup>`}s.innerHTML=h;if([...s.options].some(o=>o.value===cur))s.value=cur;}
function localSafety(){const out=[];if(!state.exam)return out;const obscene=/\b(địt|đụ|đéo|lồn|cặc|buồi|fuck|shit)\b/iu;const dangerous=/(?:cách|hướng dẫn|các bước).{0,50}(?:chế tạo|làm).{0,30}(?:bom|chất nổ|vũ khí)|(?:cách|hướng dẫn).{0,50}(?:hack|trộm|gian lận)/iu;(state.exam.examCodes||[]).forEach(c=>{(c.readQuestions||[]).forEach(q=>{const t=[q.prompt,...(q.options||[]),answerText(q),...(q.rubric||[]).map(r=>r.content)].join(' ');if(obscene.test(t))out.push({severity:'block',category:'Ngôn ngữ',code:c.code,questionNumber:q.number,message:'Có dấu hiệu từ ngữ tục tĩu/phản cảm.'});if(dangerous.test(t))out.push({severity:'block',category:'An toàn/pháp luật',code:c.code,questionNumber:q.number,message:'Có dấu hiệu hướng dẫn hành vi nguy hiểm/vi phạm.'})})});return out}
function renderSafety(){const root=$('#safetyReport'),items=[...localSafety(),...(state.aiReview?.issues||[])];root.classList.remove('hidden');root.innerHTML=items.length?`<b>Rà soát (${items.length})</b>${items.map(x=>`<div class="safety-issue"><span class="safety-badge ${x.severity||'warning'}">${x.severity==='block'?'CẦN SỬA':x.severity==='info'?'THÔNG TIN':'KIỂM TRA'}</span><div><b>${esc(x.category||'')}</b>${x.code?` · Đề ${esc(x.code)}`:''}${x.questionNumber?` · Câu ${esc(x.questionNumber)}`:''}<div>${esc(x.message||'')}</div>${x.suggestion?`<div class="tiny">Gợi ý: ${esc(x.suggestion)}</div>`:''}</div></div>`).join('')}`:'<b>Rà soát an toàn</b><div class="tiny">Chưa phát hiện cảnh báo tự động. AI vẫn có thể sai; giáo viên cần kiểm tra thủ công.</div>';}
function resetConfirm(){if($('#reviewConfirm'))$('#reviewConfirm').checked=false;updateExportGate();saveDraft('đã cập nhật')}
function updateExportGate(){if($('#exportDocxBtn'))$('#exportDocxBtn').disabled=!state.exam||!$('#reviewConfirm')?.checked||localSafety().some(x=>x.severity==='block')}
function appendChat(kind,text){const log=$('#aiChatLog');const d=document.createElement('div');d.className=kind==='user'?'chat-user':'chat-ai';d.textContent=text;log.appendChild(d);log.scrollTop=log.scrollHeight}
async function aiEdit(){if(!state.apiOk)return alert('Hãy kiểm tra AI trước.');const scope=$('#aiScope').value,req=$('#aiEditRequest').value.trim();if(!scope||!req)return alert('Hãy chọn phạm vi và nhập yêu cầu.');const [kind,ci,qi]=scope.split('|');const c=state.exam.examCodes[+ci];let target=kind.startsWith('write')?c.write:c.readQuestions[+qi];appendChat('user',req);$('#aiEditBtn').disabled=true;try{const data=await post('/api/refine',{...aiParams(),payload:buildPayload(),target:{kind,codeIndex:+ci,questionIndex:+qi,code:c.code,item:clone(target)},teacherRequest:req});state.proposal={...data,scope:{kind,ci:+ci,qi:+qi}};renderProposal();appendChat('ai',data.summary||'AI đã tạo đề xuất.');}catch(e){appendChat('ai','Lỗi: '+e.message)}finally{$('#aiEditBtn').disabled=false}}
function proposalText(p){if(!p)return '';if(p.kind==='write'||p.rubric)return JSON.stringify(p,null,2);return JSON.stringify(p,null,2)}
function renderProposal(){const b=$('#aiProposal');if(!state.proposal?.proposal){b.classList.add('hidden');b.innerHTML='';return}b.classList.remove('hidden');b.innerHTML=`<b>Đề xuất của AI</b><div class="tiny">${esc(state.proposal.summary||'')}</div><div class="proposal-preview">${esc(proposalText(state.proposal.proposal))}</div><div class="proposal-actions"><button class="btn primary" id="applyProposal">Áp dụng</button><button class="btn ghost" id="discardProposal">Bỏ qua</button></div>`;$('#applyProposal').onclick=applyProposal;$('#discardProposal').onclick=()=>{state.proposal=null;renderProposal()};}
function applyProposal(){const p=state.proposal;if(!p)return;state.history.push(clone(state.exam));if(state.history.length>10)state.history.shift();const {kind,ci,qi}=p.scope;if(kind==='read'||kind==='marking')state.exam.examCodes[ci].readQuestions[qi]=clone(p.proposal);else state.exam.examCodes[ci].write=clone(p.proposal);state.exam=distributeSingleAnswers(state.exam);state.proposal=null;state.aiReview=null;renderProposal();renderExam();renderReview();resetConfirm();$('#undoEditBtn').disabled=false;appendChat('ai','Đã áp dụng. Hãy kiểm tra lại nội dung và điểm.');}
function undoEdit(){if(!state.history.length)return;state.exam=state.history.pop();state.proposal=null;state.aiReview=null;renderExam();renderReview();resetConfirm();$('#undoEditBtn').disabled=!state.history.length;appendChat('ai','Đã hoàn tác lần chỉnh gần nhất.');}
async function aiReview(){if(!state.apiOk)return alert('Hãy kiểm tra AI trước.');if(!state.exam)return alert('Chưa có đề.');const b=$('#aiReviewBtn');b.disabled=true;b.textContent='Đang rà soát…';try{state.aiReview=await post('/api/review',{...aiParams(),payload:buildPayload(),exam:state.exam});renderSafety();appendChat('ai',state.aiReview.summary||'Đã rà soát toàn bộ đề.')}catch(e){appendChat('ai','Rà soát lỗi: '+e.message)}finally{b.disabled=false;b.textContent='🔍 AI rà soát toàn bộ'}}
function renderHealth(items=[]){const root=$('#aiHealth');if(!root)return;if(!items.length){root.classList.add('hidden');root.innerHTML='';return}root.classList.remove('hidden');root.innerHTML=items.map(x=>`<div class="health-row ${x.ok?'ok':x.skipped?'skip':'bad'}"><span class="health-provider">${esc(x.label||x.provider)}</span><span>${esc(x.message||'')}</span><span class="health-state">${x.ok?'SẴN SÀNG':x.skipped?'CHƯA CẤU HÌNH':'LỖI'}</span>${x.model?`<span class="health-model tiny">${esc(x.model)}</span>`:''}</div>`).join('')}
function syncProvider(){state.provider=provider();state.apiOk=false;state.autoRoutes=[];const p=state.provider,isAuto=p==='auto';$('#autoApiPanel').classList.toggle('hidden',!isAuto);$('#personalApiPanel').classList.toggle('hidden',isAuto||p==='cloudflare');$('#geminiGuide').href=CFG.GEMINI_GUIDE_URL||'#';const urls={gemini:'https://aistudio.google.com/apikey',openai:'https://platform.openai.com/api-keys',xai:'https://console.x.ai/',cloudflare:'https://dash.cloudflare.com/',auto:'https://dash.cloudflare.com/'};$('#providerConsole').href=urls[p];$('#geminiGuide').style.display=p==='gemini'?'inline':'none';if(isAuto){state.model='auto';state.models=['auto'];$('#modelSelect').disabled=true;$('#modelSelect').innerHTML='<option value="auto">Tự động chọn tuyến tốt nhất</option>';setApiStatus('Chưa kiểm tra hệ thống AI tự động.','neutral')}else{$('#modelSelect').innerHTML='<option>Chưa kiểm tra...</option>';$('#modelSelect').disabled=true;setApiStatus(`Chưa kiểm tra ${p==='gemini'?'Gemini':p==='openai'?'OpenAI':p==='xai'?'xAI Grok':'Cloudflare Workers AI'}.`,'neutral')}renderHealth([])}
async function testApi(){const p=provider(),key=$('#apiKey')?.value.trim()||'';if(!['auto','cloudflare'].includes(p)&&!key)return setApiStatus('Vui lòng nhập API key.','bad');const b=$('#testApiBtn');b.disabled=true;b.textContent='Đang kiểm tra…';try{const req=p==='auto'?{provider:'auto',credentials:{gemini:($('#autoGeminiKey')?.value||'').trim(),openai:($('#autoOpenAiKey')?.value||'').trim(),xai:($('#autoXaiKey')?.value||'').trim()}}:{provider:p,apiKey:key};const d=await post('/api/test-provider',req);renderHealth(d.health||[]);state.autoRoutes=d.routes||[];state.models=d.models||[];state.model=d.recommended||state.models[0]||(p==='auto'?'auto':'');if(p==='auto'){$('#modelSelect').disabled=true;$('#modelSelect').innerHTML='<option value="auto">Tự động chọn tuyến tốt nhất</option>'}else{$('#modelSelect').disabled=!state.models.length;$('#modelSelect').innerHTML=state.models.map(m=>`<option value="${esc(m)}" ${m===state.model?'selected':''}>${esc(d.modelLabels?.[m]||m)}</option>`).join('')}state.apiOk=true;setApiStatus('✓ '+(d.message||'Hệ thống AI hoạt động.'),'ok');saveDraft('đã kiểm tra hệ thống AI')}catch(e){state.apiOk=false;renderHealth(e.health||[]);setApiStatus('✕ '+e.message,'bad')}finally{b.disabled=false;b.textContent='Kiểm tra hệ thống AI'}}
// DOCX
const xEsc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
function wr(text,{b=false,i=false,sz=28}={}){return `<w:r><w:rPr>${b?'<w:b/>':''}${i?'<w:i/>':''}<w:sz w:val="28"/><w:szCs w:val="28"/><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/></w:rPr><w:t xml:space="preserve">${xEsc(text)}</w:t></w:r>`}
function wp(text='',o={}){const jc=o.align?`<w:jc w:val="${o.align}"/>`:'';return `<w:p><w:pPr>${jc}<w:spacing w:before="0" w:after="120" w:line="240" w:lineRule="auto"/></w:pPr>${wr(text,{...o,sz:28})}</w:p>`}
function wpRuns(runs=[],o={}){const jc=o.align?`<w:jc w:val="${o.align}"/>`:'';return `<w:p><w:pPr>${jc}<w:spacing w:before="0" w:after="120" w:line="240" w:lineRule="auto"/></w:pPr>${runs.map(r=>wr(r.text,{...r,sz:28})).join('')}</w:p>`}
function wpLines(text='',o={}){const jc=o.align?`<w:jc w:val="${o.align}"/>`:'';const a=String(text??'').split(/\n/);const body=a.map((s,i)=>wr(s,{...o,sz:28})+(i<a.length-1?'<w:r><w:br/></w:r>':'')).join('');return `<w:p><w:pPr>${jc}<w:spacing w:before="0" w:after="120" w:line="240" w:lineRule="auto"/></w:pPr>${body}</w:p>`}
function tc(content,{span=1,vMerge=null,fill=null,width=null}={}){return `<w:tc><w:tcPr>${span>1?`<w:gridSpan w:val="${span}"/>`:''}${vMerge==='restart'?'<w:vMerge w:val="restart"/>':vMerge==='continue'?'<w:vMerge/>':''}${fill?`<w:shd w:fill="${fill}"/>`:''}${width?`<w:tcW w:w="${width}" w:type="dxa"/>`:''}<w:tcMar><w:top w:w="70" w:type="dxa"/><w:left w:w="80" w:type="dxa"/><w:bottom w:w="70" w:type="dxa"/><w:right w:w="80" w:type="dxa"/></w:tcMar><w:vAlign w:val="center"/></w:tcPr>${content||wp('')}</w:tc>`}
function tr(cells){return `<w:tr>${cells.join('')}</w:tr>`}
function tbl(rows,widths=[]){const total=widths.length?widths.reduce((a,b)=>a+n(b),0):9600;return `<w:tbl><w:tblPr><w:tblW w:w="${total}" w:type="dxa"/><w:tblLayout w:type="fixed"/><w:jc w:val="center"/><w:tblBorders><w:top w:val="single" w:sz="6"/><w:left w:val="single" w:sz="6"/><w:bottom w:val="single" w:sz="6"/><w:right w:val="single" w:sz="6"/><w:insideH w:val="single" w:sz="4"/><w:insideV w:val="single" w:sz="4"/></w:tblBorders></w:tblPr>${widths.length?`<w:tblGrid>${widths.map(w=>`<w:gridCol w:w="${w}"/>`).join('')}</w:tblGrid>`:''}${rows.join('')}</w:tbl>`}
function headerDoc(kind='bundle',code=''){const agency=$('#agency').value.trim(),s1=$('#schoolLine1').value.trim(),s2=$('#schoolLine2').value.trim(),year=$('#schoolYear').value.trim(),etype=$('#examType').value;const school=wp(agency,{align:'center',after:0})+wp(s1,{b:true,align:'center',after:0})+wp(s2,{b:true,align:'center'});if(kind==='marking'){const right=wp(`HƯỚNG DẪN CHẤM ${etype}`,{b:true,align:'center',after:0})+wp(`NĂM HỌC ${year}`,{b:true,align:'center',after:0})+wp(`MÔN: NGỮ VĂN – LỚP ${state.grade}`,{b:true,align:'center'});return tbl([tr([tc(school),tc(right)])],[4700,4900])}let right=wp(etype,{b:true,align:'center',after:0})+wp(`NĂM HỌC ${year}`,{b:true,align:'center',after:0})+wp(`MÔN: NGỮ VĂN – LỚP ${state.grade}`,{b:true,align:'center',after:kind==='exam'?0:120});if(kind==='exam'){right+=wpRuns([{text:'Thời gian làm bài: '},{text:String($('#duration').value),b:true},{text:' phút '},{text:'(không kể thời gian phát đề)',i:true}],{align:'center',after:0});right+=wp(`Đề gồm có ${$('#examPages')?.value.trim()||'…'} trang`,{i:true,align:'center'})}const rows=[tr([tc(school),tc(right)])];rows.push(tr([tc(wp(officialLabel(code),{b:true,align:'center'})),tc(wp(''))]));if(kind==='exam')rows.push(tr([tc(wpRuns([{text:'Họ và tên học sinh: ',b:true},{text:'............................................................................................. '},{text:'Lớp: ',b:true},{text:'........................'}],{align:'left'}),{span:2})]));return tbl(rows,[4700,4900])}
function pageBreak(){return '<w:p><w:r><w:br w:type="page"/></w:r></w:p>'}
function bundleIntroDoc(){const o=state.objectives||{...objectiveBase(),qualities:'Chưa tạo bằng AI'};let x=headerDoc('bundle');x+=wp('I. MỤC TIÊU ĐỀ KIỂM TRA',{b:true});x+=wpRuns([{text:'1. Năng lực: ',b:true},{text:o.competencyIntro}],{align:'both'});x+=wp(`– Phần Đọc - hiểu: ${o.readScope}`,{align:'both'});x+=wp(`– Phần tiếng Việt: ${o.vietnameseScope}`,{align:'both'});x+=wp(`– Phần Viết: ${o.writeScope}`,{align:'both'});x+=wpRuns([{text:'2. Phẩm chất: ',b:true},{text:o.qualities}],{align:'both'});x+=wp('II. HÌNH THỨC ĐỀ KIỂM TRA',{b:true});x+=wp(formText(),{align:'both'});x+=wp('III. THIẾT LẬP MA TRẬN, ĐẶC TẢ',{b:true});x+=wp('1. Ma trận',{b:true});x+=matrixDoc();x+=wp('2. Bảng đặc tả',{b:true});x+=specDoc();x+=wpRuns([{text:'IV. ĐỀ KIỂM TRA ',b:true},{text:'(trang sau)',i:true}],{align:'left'});return x}
